(window.SOAL_PART = window.SOAL_PART || {})["bahasa_inggris"] = {"nama": "Bahasa Inggris", "soal": [
    {"id": "e1", "pertanyaan": "The military commander _____ his troops before the mission.", "pilihan": ["briefed", "brief", "briefs", "was brief"], "jawaban": 0, "pembahasan": "JAWABAN: briefed\nPast tense digunakan karena 'before the mission' menunjukkan kejadian lampau.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e2", "pertanyaan": "Word closest in meaning to 'valiant':", "pilihan": ["cowardly", "brave", "weak", "careless"], "jawaban": 1, "pembahasan": "JAWABAN: brave\nValiant = gagah berani. Sinonim: brave (berani).\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e3", "pertanyaan": "The soldiers are trained to _____ under any circumstances.", "pilihan": ["survives", "surviving", "survived", "survive"], "jawaban": 3, "pembahasan": "JAWABAN: survive\n'to' + bare infinitive. 'to survive' adalah bentuk yang benar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e4", "pertanyaan": "'Swa Bhuwana Paksa' means:", "pilihan": ["Victory at All Cost", "At sea we are glorious", "Wings of the Motherland", "On the Ground We Stand"], "jawaban": 2, "pembahasan": "JAWABAN: Wings of the Motherland\nSwa Bhuwana Paksa = Wings of the Motherland, semboyan TNI AU.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e5", "pertanyaan": "If I _____ the training, I would have qualified.", "pilihan": ["had completed", "have completed", "complete", "completed"], "jawaban": 0, "pembahasan": "JAWABAN: had completed\nConditional type 3: If + had + V3, would have + V3.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "conditional"},
    {"id": "e6", "pertanyaan": "The report _____ by the intelligence officer yesterday.", "pilihan": ["submitted", "was submitted", "has submitted", "is submitted"], "jawaban": 1, "pembahasan": "JAWABAN: was submitted\nPassive voice past tense: was/were + V3. 'yesterday' = lampau.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "tenses"},
    {"id": "e7", "pertanyaan": "Antonym of 'hostile':", "pilihan": ["dangerous", "military", "aggressive", "friendly"], "jawaban": 3, "pembahasan": "JAWABAN: friendly\nHostile = bermusuhan. Antonim: friendly (bersahabat).\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e8", "pertanyaan": "_____ the heavy rain, the troops continued their patrol.", "pilihan": ["Because", "Although", "Despite", "However"], "jawaban": 2, "pembahasan": "JAWABAN: Despite\n'Despite' + noun phrase. 'Although' butuh clause lengkap.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e9", "pertanyaan": "'Reconnaissance' in military context means:", "pilihan": ["Observation of enemy territory", "Military rank", "Combat training", "A type of weapon"], "jawaban": 0, "pembahasan": "JAWABAN: Observation of enemy territory\nReconnaissance = pengintaian, observasi wilayah musuh.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e10", "pertanyaan": "She asked me where _____ stationed.", "pilihan": ["was I", "I was", "am I", "I am"], "jawaban": 1, "pembahasan": "JAWABAN: I was\nDalam indirect speech, susunan normal: subject + verb. 'where I was'.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e11", "pertanyaan": "Choose the correct sentence:", "pilihan": ["The general not agree", "The general don't agree", "The general doesn't agrees", "The general doesn't agree"], "jawaban": 3, "pembahasan": "JAWABAN: The general doesn't agree\nSubjek tunggal + doesn't + V1. 'doesn't agree' benar.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e12", "pertanyaan": "The word 'integrity' means:", "pilihan": ["Speed and agility", "Physical strength", "Moral wholeness and honesty", "Military rank"], "jawaban": 2, "pembahasan": "JAWABAN: Moral wholeness and honesty\nIntegrity = integritas, kejujuran dan prinsip moral yang kuat.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e13", "pertanyaan": "The commander ordered his troops _____ their positions.", "pilihan": ["to hold", "holding", "held", "hold"], "jawaban": 0, "pembahasan": "JAWABAN: to hold\n'ordered + object + to + V1'. Correct: ordered them to hold.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e14", "pertanyaan": "Word opposite in meaning to 'mandatory':", "pilihan": ["required", "optional", "essential", "compulsory"], "jawaban": 1, "pembahasan": "JAWABAN: optional\nMandatory = wajib. Antonim: optional (pilihan/tidak wajib).\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e15", "pertanyaan": "The troops _____ in the jungle for three days before rescue arrived.", "pilihan": ["have survive", "survive", "survived", "had survived"], "jawaban": 3, "pembahasan": "JAWABAN: had survived\nPast perfect: had + V3 untuk kejadian sebelum kejadian lampau lain.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e16", "pertanyaan": "'Logistics' in military operations refers to:", "pilihan": ["Weapons design", "Combat strategy", "Supply and transport management", "Intelligence gathering"], "jawaban": 2, "pembahasan": "JAWABAN: Supply and transport management\nLogistics = manajemen pasokan, transportasi, dan distribusi dalam operasi militer.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e17", "pertanyaan": "_____ soldier trains, _____ prepared he will be.", "pilihan": ["The harder a / the more", "If a / but", "Although a / yet", "If a / the more"], "jawaban": 0, "pembahasan": "JAWABAN: The harder a / the more\nPola 'the + comparative ..., the + comparative ...' menyatakan makin ... makin .... 'The harder a soldier trains, the more prepared he will be' = makin giat prajurit berlatih, makin siap ia. Opsi lain tidak membentuk pola yang sejajar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e18", "pertanyaan": "The word 'fortify' means:", "pilihan": ["To weaken", "To strengthen a position", "To retreat", "To surrender"], "jawaban": 1, "pembahasan": "JAWABAN: To strengthen a position\nFortify = memperkuat posisi pertahanan atau struktur militer.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e19", "pertanyaan": "Choose the grammatically correct sentence:", "pilihan": ["Each soldier must carries his weapon", "Each soldiers must carries their weapon", "Each soldiers must carry their weapon", "Each soldier must carry his weapon"], "jawaban": 3, "pembahasan": "JAWABAN: Each soldier must carry his weapon\n'Each' + singular noun + singular verb. 'Each soldier must carry' benar.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e20", "pertanyaan": "'The mission was accomplished' is an example of:", "pilihan": ["Indirect speech", "Active voice", "Passive voice", "Direct speech"], "jawaban": 2, "pembahasan": "JAWABAN: Passive voice\nPassive voice: be + V3. 'was accomplished' = pasif.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "passive"},
    {"id": "e21", "pertanyaan": "The word 'deploy' in military context means:", "pilihan": ["To position forces strategically", "To surrender", "To negotiate", "To retreat"], "jawaban": 0, "pembahasan": "JAWABAN: To position forces strategically\nDeploy = menempatkan pasukan secara strategis di posisi siap tempur. TRIK: ingat 'deploy' di software juga artinya menempatkan/meluncurkan.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e22", "pertanyaan": "Choose the correct comparative sentence:", "pilihan": ["This mission is more harder than the last", "This mission is harder than the last", "This mission is more hard than the last", "This mission is hardest than the last"], "jawaban": 1, "pembahasan": "JAWABAN: This mission is harder than the last\nComparative: adjective + -er + than. 'harder than' benar. Jangan pakai 'more' + er bersamaan. TRIK: 1 atau 2 suku kata = tambah -er, 3+ suku kata = pakai more.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e23", "pertanyaan": "'The general, _____ was highly respected, retired last year.'", "pilihan": ["whom", "whose", "which", "who"], "jawaban": 3, "pembahasan": "JAWABAN: who\n'who' untuk orang sebagai subjek relative clause. 'whom' untuk objek. 'The general, who was respected' = benar.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "passive"},
    {"id": "e24", "pertanyaan": "What does 'strategic' mean?", "pilihan": ["Defensive only", "Random and unplanned", "Related to important long-term goals", "Quick and immediate"], "jawaban": 2, "pembahasan": "JAWABAN: Related to important long-term goals\nStrategic = berkaitan dengan strategi jangka panjang yang penting. Antonim: tactical (jangka pendek/teknis).\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e25", "pertanyaan": "The soldiers _____ been training for six months when the mission started.", "pilihan": ["had", "has", "were", "have"], "jawaban": 0, "pembahasan": "JAWABAN: had\nPast perfect: had + V3. 'had been training' = past perfect continuous. Gunakan saat satu kejadian lampau terjadi sebelum kejadian lampau lainnya.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "tenses"},
    {"id": "e26", "pertanyaan": "'Morale' means:", "pilihan": ["Military rank", "Confidence and discipline of a group", "A type of weapon", "Battle strategy"], "jawaban": 1, "pembahasan": "JAWABAN: Confidence and discipline of a group\nMorale = semangat/moral/kepercayaan diri kelompok. 'High morale' = semangat tinggi. Penting dalam konteks kepemimpinan militer.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e27", "pertanyaan": "Which sentence uses 'despite' correctly?", "pilihan": ["Despite that it rained, they continued", "Despite the raining, they continued", "Despite of the rain, they continued", "Despite the rain, they continued"], "jawaban": 3, "pembahasan": "JAWABAN: Despite the rain, they continued\nDespite + noun phrase (tanpa 'of'). 'Despite the rain' benar. TRIK: despite/in spite of + noun, although/even though + clause.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "agreement"},
    {"id": "e28", "pertanyaan": "The word 'hierarchy' refers to:", "pilihan": ["A training method", "A type of weapon", "A system of ranking by authority", "A battle formation"], "jawaban": 2, "pembahasan": "JAWABAN: A system of ranking by authority\nHierarchy = hierarki, sistem tingkatan/jabatan berdasarkan otoritas. Sangat relevan dalam konteks militer dan organisasi.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e29", "pertanyaan": "She asked the commander _____ the mission would start.", "pilihan": ["when", "which", "who", "that"], "jawaban": 0, "pembahasan": "JAWABAN: when\nIndirect question membutuhkan kata tanya, bukan 'that'. Konteks kalimat menanyakan WAKTU mulai misi, jadi kata tanya yang tepat adalah 'when'.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e30", "pertanyaan": "'The officer was commended for his bravery.' What does 'commended' mean?", "pilihan": ["Criticized", "Officially praised", "Punished", "Ignored"], "jawaban": 1, "pembahasan": "JAWABAN: Officially praised\nCommend = memuji secara resmi/memberi penghargaan. Antonim: reprimand (menegur). TRIK: commend = command dalam perang bisa juga berarti pujian formal.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "passive"},
    {"id": "e31", "pertanyaan": "Choose the correct past tense: 'The troops _____ through the jungle for three days.'", "pilihan": ["were marching", "had marched", "march", "marched"], "jawaban": 3, "pembahasan": "JAWABAN: marched\nSimple past tense digunakan untuk kejadian lampau yang selesai. 'marched' benar.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "vocabulary"},
    {"id": "e32", "pertanyaan": "'Perimeter' in military context means:", "pilihan": ["A training exercise", "The center of the base", "The outer boundary of a defended area", "A type of weapon"], "jawaban": 2, "pembahasan": "JAWABAN: The outer boundary of a defended area\nPerimeter = garis batas pertahanan terluar. 'Secure the perimeter' = amankan garis batas pertahanan.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e33", "pertanyaan": "Which is grammatically correct?", "pilihan": ["Neither the soldiers nor the commander was ready", "Neither the soldiers nor the commander were ready", "Neither the soldiers nor the commander are ready", "Neither the soldiers nor the commander is ready"], "jawaban": 0, "pembahasan": "JAWABAN: Neither the soldiers nor the commander was ready\nAturan 'neither ... nor' mengikuti subjek TERDEKAT (proximity rule). Subjek terdekat = 'the commander' (tunggal), jadi verb harus tunggal dan sesuai konteks masa lalu: 'was ready'. 'were ready' salah karena mengikuti 'soldiers'; 'is ready' salah karena bukan bentuk lampau.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "vocabulary"},
    {"id": "e34", "pertanyaan": "'The report must _____ by 5 PM today.'", "pilihan": ["submits", "be submitted", "submitting", "submit"], "jawaban": 1, "pembahasan": "JAWABAN: be submitted\nPassive voice setelah modal: must be + V3. 'must be submitted' benar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e35", "pertanyaan": "'Camouflage' means:", "pilihan": ["To attack directly", "To retreat safely", "To reveal position", "To conceal by blending with surroundings"], "jawaban": 3, "pembahasan": "JAWABAN: To conceal by blending with surroundings\nCamouflage = penyamaran untuk menyatu dengan lingkungan agar tidak terlihat musuh.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e36", "pertanyaan": "Choose the correct superlative: 'This is the _____ training we have ever done.'", "pilihan": ["much difficult", "more difficult", "most difficult", "difficultest"], "jawaban": 2, "pembahasan": "JAWABAN: most difficult\nSuperlative untuk adjective 2+ suku kata: the most + adjective. 'most difficult' benar.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "tenses"},
    {"id": "e37", "pertanyaan": "'The commander asked the troops _____ ready for inspection.'", "pilihan": ["to be", "been", "be", "being"], "jawaban": 0, "pembahasan": "JAWABAN: to be\nasked + object + to + V1. 'asked them to be ready' benar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e38", "pertanyaan": "'Alliance' means:", "pilihan": ["A type of weapon", "A formal agreement between groups for mutual benefit", "A battle formation", "A military rank"], "jawaban": 1, "pembahasan": "JAWABAN: A formal agreement between groups for mutual benefit\nAlliance = aliansi, kerjasama formal antara negara atau kelompok untuk tujuan bersama.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e39", "pertanyaan": "'The general spoke as if he _____ the battle himself.'", "pilihan": ["would win", "wins", "won", "had won"], "jawaban": 3, "pembahasan": "JAWABAN: had won\n'as if' + past perfect = tidak nyata. 'had won' = unreal past condition.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "subjunctive"},
    {"id": "e40", "pertanyaan": "Which sentence is correct?", "pilihan": ["The number of soldiers have increased", "The number of soldiers are increasing", "The number of soldiers is increasing", "A number of soldiers is increasing"], "jawaban": 2, "pembahasan": "JAWABAN: The number of soldiers is increasing\n'The number of' = singular (fokus ke angka). 'A number of' = plural (fokus ke banyak). 'The number is' benar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e41", "pertanyaan": "'Ceasefire' means:", "pilihan": ["A temporary stop in fighting", "To advance position", "To surrender completely", "To start fighting"], "jawaban": 0, "pembahasan": "JAWABAN: A temporary stop in fighting\nCeasefire = gencatan senjata, penghentian sementara pertempuran.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e42", "pertanyaan": "'The equipment _____ tested before being used in the field.'", "pilihan": ["must", "must be", "must been", "must being"], "jawaban": 1, "pembahasan": "JAWABAN: must be\nPassive: must be + V3. 'must be tested' benar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "agreement"},
    {"id": "e43", "pertanyaan": "'Intelligence' in military context refers to:", "pilihan": ["Physical fitness", "Weapons technology", "Military strength", "Information gathering and analysis"], "jawaban": 3, "pembahasan": "JAWABAN: Information gathering and analysis\nIntelligence = intelijen, pengumpulan dan analisis informasi strategis militer.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e44", "pertanyaan": "Choose the correct sentence:", "pilihan": ["Had I known, I would act", "Had I known, I will act", "If I had known, I would have acted", "If I knew, I would have acted"], "jawaban": 2, "pembahasan": "JAWABAN: If I had known, I would have acted\nConditional type 3 (pengandaian masa lalu): If + had + V3, would have + V3. 'If I had known, I would have acted' paling tepat. Opsi 'Had I known, I would act' salah karena hasilnya harus 'would have + V3'.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e45", "pertanyaan": "'Regiment' is:", "pilihan": ["A military unit typically consisting of several battalions", "A type of weapon", "A military exercise", "A small team of 2-5 soldiers"], "jawaban": 0, "pembahasan": "JAWABAN: A military unit typically consisting of several battalions\nRegiment = resimen, unit militer besar yang terdiri dari beberapa batalyon.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e46", "pertanyaan": "'The mission _____ completed successfully if the weather had been better.'", "pilihan": ["was", "would have been", "would be", "will be"], "jawaban": 1, "pembahasan": "JAWABAN: would have been\nConditional type 3 passive: would have been + V3. 'would have been completed' benar.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "conditional"},
    {"id": "e47", "pertanyaan": "'Not only _____ the enemy, but they also captured the base.'", "pilihan": ["defeated they", "they had defeated", "they defeated", "did they defeat"], "jawaban": 3, "pembahasan": "JAWABAN: did they defeat\nInversi setelah 'not only': not only + auxiliary + subject + verb. 'did they defeat' benar.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e48", "pertanyaan": "'Barracks' means:", "pilihan": ["A training ground", "A type of weapon", "Military housing/shelter for soldiers", "A battle formation"], "jawaban": 2, "pembahasan": "JAWABAN: Military housing/shelter for soldiers\nBarracks = barak, tempat tinggal/penampungan prajurit militer.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e49", "pertanyaan": "'The officer suggested that the troops _____ the area immediately.'", "pilihan": ["evacuate", "evacuates", "evacuated", "evacuating"], "jawaban": 0, "pembahasan": "JAWABAN: evacuate\nSubjunctive setelah 'suggested that': base form verb (V1). 'evacuate' benar.\nINGAT: Subjunctive setelah suggest/demand/insist/essential that: pakai kata kerja dasar (V1) tanpa -s.", "topik": "subjunctive"},
    {"id": "e50", "pertanyaan": "'The soldiers are used _____ hard training every day.'", "pilihan": ["to do", "to doing", "do", "doing"], "jawaban": 1, "pembahasan": "JAWABAN: to doing\n'be used to + V-ing' = terbiasa melakukan. 'used to doing' benar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e51", "pertanyaan": "'Under no circumstances _____ the classified information.'", "pilihan": ["you share", "share you", "you must share", "must you share"], "jawaban": 3, "pembahasan": "JAWABAN: must you share\nInversi setelah negative adverb: Under no circumstances + auxiliary + subject + verb. 'must you share' benar.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e52", "pertanyaan": "'Maneuver' means:", "pilihan": ["To retreat", "A type of weapon", "A planned movement of military forces", "To surrender"], "jawaban": 2, "pembahasan": "JAWABAN: A planned movement of military forces\nManeuver = manuver, pergerakan terencana pasukan militer untuk mendapatkan posisi strategis.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e53", "pertanyaan": "'The general, along with his staff, _____ arrived.'", "pilihan": ["has", "are", "were", "have"], "jawaban": 0, "pembahasan": "JAWABAN: has\n'along with' tidak mengubah subjek. Subjek tetap 'the general' (singular) → 'has'.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "agreement"},
    {"id": "e54", "pertanyaan": "'Ammunition' refers to:", "pilihan": ["Food supplies", "Bullets, shells, and other projectiles", "Medical equipment", "Communication devices"], "jawaban": 1, "pembahasan": "JAWABAN: Bullets, shells, and other projectiles\nAmmunition = amunisi, peluru, proyektil, bahan peledak untuk senjata.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e55", "pertanyaan": "'The commander demanded that the report _____ accurate.'", "pilihan": ["was", "were", "is", "be"], "jawaban": 3, "pembahasan": "JAWABAN: be\nSubjunctive setelah 'demanded that': base form verb (V1). 'be' benar.\nINGAT: Subjunctive setelah suggest/demand/insist/essential that: pakai kata kerja dasar (V1) tanpa -s.", "topik": "subjunctive"},
    {"id": "e56", "pertanyaan": "'It is essential that every soldier _____ the code of conduct.'", "pilihan": ["followed", "following", "follow", "follows"], "jawaban": 2, "pembahasan": "JAWABAN: follow\nSubjunctive setelah 'it is essential that': base form verb (V1). 'follow' benar.\nINGAT: Subjunctive setelah suggest/demand/insist/essential that: pakai kata kerja dasar (V1) tanpa -s.", "topik": "subjunctive"},
    {"id": "e57", "pertanyaan": "'The soldiers _____ the enemy position before dawn.'", "pilihan": ["attacked", "were attacking", "had attacked", "attack"], "jawaban": 0, "pembahasan": "JAWABAN: attacked\nSimple past untuk kejadian lampau selesai. 'attacked' benar.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e58", "pertanyaan": "'Convoy' means:", "pilihan": ["A single vehicle", "A group of vehicles traveling together for protection", "A type of weapon", "A military rank"], "jawaban": 1, "pembahasan": "JAWABAN: A group of vehicles traveling together for protection\nConvoy = konvoi, sekelompok kendaraan yang bergerak bersama untuk perlindungan.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e59", "pertanyaan": "'The general insisted that his orders _____ followed without question.'", "pilihan": ["were", "been", "are", "be"], "jawaban": 3, "pembahasan": "JAWABAN: be\nSubjunctive setelah 'insisted that': base form verb (V1). 'be' benar.\nINGAT: Subjunctive setelah suggest/demand/insist/essential that: pakai kata kerja dasar (V1) tanpa -s.", "topik": "subjunctive"},
    {"id": "e60", "pertanyaan": "'Hardly _____ the base when the alarm sounded.'", "pilihan": ["did we leave", "we had left", "had we left", "we left"], "jawaban": 2, "pembahasan": "JAWABAN: had we left\nInversi setelah 'hardly': Hardly + had + subject + V3. 'had we left' benar.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e61", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["Each of the pilots have completed night-flying training.", "The radar system detects any aircraft in range.", "Our squadron was deployed to the border last month.", "The pilot has flown over 2,000 hours since 2010."], "jawaban": 0, "pembahasan": "JAWABAN: Each of the pilots have completed night-flying training.\nSubjek each of the pilots adalah singular, jadi verb harus has completed, bukan have. Kalimat lain benar secara grammar.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e62", "pertanyaan": "The runway ______ every morning before the first aircraft takes off.", "pilihan": ["is inspect", "is inspected", "inspected", "inspect"], "jawaban": 1, "pembahasan": "JAWABAN: is inspected\nKalimat pasif simple present: runway di-inspeksi, pola is + V3. Jadi is inspected.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e63", "pertanyaan": "Sinonim dari kata ALTITUDE adalah ...", "pilihan": ["width", "depth", "length", "height"], "jawaban": 3, "pembahasan": "JAWABAN: height\nAltitude berarti ketinggian di atas permukaan laut. Sinonim yang tepat adalah height.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e64", "pertanyaan": "Antonim dari kata TAKEOFF adalah ...", "pilihan": ["ascent", "climb", "landing", "departure"], "jawaban": 2, "pembahasan": "JAWABAN: landing\nTakeoff berarti lepas landas, antonimnya adalah landing (pendaratan). Departure, ascent, climb adalah sinonim atau kata terkait.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e65", "pertanyaan": "The Indonesian Air Force maintains several airbases across the archipelago.\nEach airbase is responsible for protecting its own airspace.\n\nWhat is the main idea of the text?", "pilihan": ["The Air Force operates many airbases that guard their airspace", "Airspace protection is not important", "Only one airbase protects the whole country", "Airbases only exist on Java island"], "jawaban": 0, "pembahasan": "JAWABAN: The Air Force operates many airbases that guard their airspace\nTeks menjelaskan bahwa TNI AU memiliki beberapa pangkalan udara yang bertanggung jawab melindungi wilayah udaranya masing-masing. Jadi ide utamanya adalah pilihan kedua.\nINGAT: Soal bacaan: jawabannya selalu ada di dalam teks, cari kalimat kuncinya.", "topik": "agreement"},
    {"id": "e66", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["Neither the commander nor his officers were present.", "The number of aircraft in the hangar are increasing.", "Every missile has been tested carefully.", "The fleet is ready for the exercise."], "jawaban": 1, "pembahasan": "JAWABAN: The number of aircraft in the hangar are increasing.\nThe number of bersifat singular, jadi verb-nya is increasing, bukan are. Subjek utama adalah the number, bukan aircraft.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e67", "pertanyaan": "The pilots ______ the mission before dawn if the weather had been clear.", "pilihan": ["will start", "would start", "started", "would have started"], "jawaban": 3, "pembahasan": "JAWABAN: would have started\nKondisi if the weather had been clear adalah past unreal conditional, pola would have + V3. Jadi would have started.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "conditional"},
    {"id": "e68", "pertanyaan": "Apa arti idiom 'to wing it'?", "pilihan": ["Berangkat tepat waktu", "Terbang tinggi", "Melakukan sesuatu tanpa persiapan", "Memperbaiki sayap pesawat"], "jawaban": 2, "pembahasan": "JAWABAN: Melakukan sesuatu tanpa persiapan\nIdiom to wing it berarti melakukan sesuatu secara spontan tanpa persiapan matang. Terkait sayap (wing) pesawat tetapi maknanya kiasan.\nINGAT: Idiom tidak bisa diterjemahkan kata per kata — hafalkan makna keseluruhannya.", "topik": "vocabulary"},
    {"id": "e69", "pertanyaan": "Sinonim dari kata PATROL adalah ...", "pilihan": ["inspection tour", "repair", "training", "storage"], "jawaban": 0, "pembahasan": "JAWABAN: inspection tour\nPatrol berarti patroli atau kegiatan pengawasan/penjagaan. Inspection tour (tur inspeksi) adalah sinonim paling tepat.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e70", "pertanyaan": "Antonim dari kata MINIMUM adalah ...", "pilihan": ["lowest", "maximum", "smallest", "least"], "jawaban": 1, "pembahasan": "JAWABAN: maximum\nMinimum berarti paling kecil, antonimnya maximum (paling besar). Least, lowest, smallest adalah sinonim.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e71", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["She suggested that he report to the base immediately.", "He acts as if he knows everything about missiles.", "If I were the commander, I would order a patrol.", "I wish the weather is better for the flight."], "jawaban": 3, "pembahasan": "JAWABAN: I wish the weather is better for the flight.\n'I wish' diikuti pengandaian yang tidak nyata, jadi bentuknya harus lampau: 'I wish the weather WERE better'. Penulisan 'is' jelas salah karena menyatakan kenyataan sekarang. Kalimat lain sudah benar (subjunctive 'were', 'suggested that + V1', 'as if + present').\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e72", "pertanyaan": "The fuselage is the main body of an aircraft.\nIt holds the crew, passengers, and cargo.\nThe wings and tail are attached to it.\n\nWhat is the fuselage?", "pilihan": ["The landing gear", "The engine of the plane", "The main body of the aircraft", "The tail fin only"], "jawaban": 2, "pembahasan": "JAWABAN: The main body of the aircraft\nTeks menyebutkan fuselage adalah badan utama pesawat yang menampung awak, penumpang, dan kargo. Jadi jawabannya main body of the aircraft.\nINGAT: Soal bacaan: jawabannya selalu ada di dalam teks, cari kalimat kuncinya.", "topik": "vocabulary"},
    {"id": "e73", "pertanyaan": "Hardly ______ the hangar when the alarm sounded.", "pilihan": ["had the pilot left", "the pilot had left", "the pilot left", "left the pilot"], "jawaban": 0, "pembahasan": "JAWABAN: had the pilot left\nHardly diikuti inversi (auxiliary + subject + verb). Polanya Hardly had the pilot left ... when ....\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e74", "pertanyaan": "Apa arti idiom 'to be in the loop'?", "pilihan": ["Berada di luar sistem", "Tetap mendapat informasi terkini", "Berputar-putar di udara", "Berada di dalam kokpit"], "jawaban": 1, "pembahasan": "JAWABAN: Tetap mendapat informasi terkini\nTo be in the loop berarti tetap mendapat informasi terbaru dan terlibat dalam komunikasi. Umum digunakan di konteks militer dan kerja tim.\nINGAT: Idiom tidak bisa diterjemahkan kata per kata — hafalkan makna keseluruhannya.", "topik": "idiom"},
    {"id": "e75", "pertanyaan": "Sinonim dari kata MISSILE adalah ...", "pilihan": ["uniform", "shield", "radar", "projectile"], "jawaban": 3, "pembahasan": "JAWABAN: projectile\nMissile adalah peluru kendali, sinonim terdekat adalah projectile (proyektil/peluru). Shield, radar, uniform tidak tepat.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e76", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["Each wing has its own radar station.", "The crew is ready for takeoff.", "The equipment were moved to the new airbase.", "Air traffic control directs every landing."], "jawaban": 2, "pembahasan": "JAWABAN: The equipment were moved to the new airbase.\nEquipment adalah uncountable noun dan bersifat singular, jadi verb-nya was moved, bukan were. Kalimat lain benar.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e77", "pertanyaan": "The soldiers are ______ guard duty at the main gate tonight.", "pilihan": ["on", "at", "over", "in"], "jawaban": 0, "pembahasan": "JAWABAN: on\nFrasa yang benar adalah on guard duty (sedang bertugas jaga). Preposisi on adalah pilihan yang tepat.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "preposition"},
    {"id": "e78", "pertanyaan": "Not until the radar detected the target ______ the order to launch.", "pilihan": ["gave the commander", "did the commander give", "the commander did give", "the commander gave"], "jawaban": 1, "pembahasan": "JAWABAN: did the commander give\nKalimat diawali Not until membutuhkan inversi: did + subject + verb. Jadi did the commander give.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e79", "pertanyaan": "Sinonim dari kata AIRCRAFT adalah ...", "pilihan": ["engine", "hangar", "vehicle", "airplane"], "jawaban": 3, "pembahasan": "JAWABAN: airplane\nAircraft berarti pesawat terbang. Airplane adalah sinonim yang paling tepat; vehicle terlalu umum, engine dan hangar berbeda makna.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e80", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["The captain, along with his crew, is on board.", "Ten kilometers is a long distance to patrol.", "The news about the exercise are encouraging.", "Every pilot and every mechanic has a role."], "jawaban": 2, "pembahasan": "JAWABAN: The news about the exercise are encouraging.\nNews adalah uncountable noun yang bersifat singular, jadi verb-nya is encouraging, bukan are. Kalimat lain benar.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e81", "pertanyaan": "If the squadron ______ more fuel, it could extend its patrol range.", "pilihan": ["had", "have", "having", "has"], "jawaban": 0, "pembahasan": "JAWABAN: had\nKondisi present unreal conditional memakai if + past tense (had). Hasilnya could + V1. Jadi had.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "conditional"},
    {"id": "e82", "pertanyaan": "Apa arti idiom 'on the radar'?", "pilihan": ["Berbahaya sekali", "Sedang diperhatikan atau dipantau", "Sudah dilupakan", "Di luar jangkauan"], "jawaban": 1, "pembahasan": "JAWABAN: Sedang diperhatikan atau dipantau\nOn the radar berarti sesuatu sedang diperhatikan, dipantau, atau menjadi perhatian. Istilah ini berasal dari layar radar.\nINGAT: Idiom tidak bisa diterjemahkan kata per kata — hafalkan makna keseluruhannya.", "topik": "idiom"},
    {"id": "e83", "pertanyaan": "Antonim dari kata OFFENSIVE adalah ...", "pilihan": ["hostile", "aggressive", "attacking", "defensive"], "jawaban": 3, "pembahasan": "JAWABAN: defensive\nOffensive berarti bersifat menyerang, antonimnya defensive (bertahan). Aggressive, attacking, hostile semuanya berkonotasi menyerang.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e84", "pertanyaan": "The F-16 fighters took off from the airbase at dawn.\nThey flew in formation toward the training area.\nTheir mission was to practice intercepting hostile aircraft.\n\nWhat was the mission of the F-16 fighters?", "pilihan": ["To repair the runway", "To transport cargo", "To practice intercepting hostile aircraft", "To land on an aircraft carrier"], "jawaban": 2, "pembahasan": "JAWABAN: To practice intercepting hostile aircraft\nTeks menyebutkan misi mereka adalah berlatih mencegat pesawat musuh. Jawaban ada di kalimat ketiga paragraf.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "passive"},
    {"id": "e85", "pertanyaan": "Rarely ______ such a difficult rescue operation.", "pilihan": ["have we seen", "we saw", "saw we", "we have seen"], "jawaban": 0, "pembahasan": "JAWABAN: have we seen\nRarely di awal kalimat membutuhkan inversi: auxiliary have + subject we + V3. Jadi have we seen.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e86", "pertanyaan": "Sinonim dari kata SQUADRON adalah ...", "pilihan": ["fleet", "unit of aircraft", "platoon", "unit"], "jawaban": 1, "pembahasan": "JAWABAN: unit of aircraft\nSquadron dalam konteks penerbangan adalah kesatuan pesawat terbang (unit of aircraft). Fleet untuk kapal, platoon untuk infanteri.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e87", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["The pilot whom I met yesterday is a veteran.", "The aircraft that was repaired is ready.", "The base which is located near the coast has a long runway.", "The technician which fixed the radar is very skilled."], "jawaban": 3, "pembahasan": "JAWABAN: The technician which fixed the radar is very skilled.\nUntuk orang harus memakai who/that, bukan which. Seharusnya The technician who fixed the radar.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e88", "pertanyaan": "The commander demanded that every soldier ______ the regulation.", "pilihan": ["is obeying", "obeys", "obey", "obeyed"], "jawaban": 2, "pembahasan": "JAWABAN: obey\nSetelah kata kerja demand (subjunctive), verb memakai bentuk dasar tanpa -s. Jadi obey, bukan obeys.\nINGAT: Subjunctive setelah suggest/demand/insist/essential that: pakai kata kerja dasar (V1) tanpa -s.", "topik": "subjunctive"},
    {"id": "e89", "pertanyaan": "Apa arti idiom 'to break the ice'?", "pilihan": ["Mencairkan suasana canggung", "Merusak peralatan", "Menghentikan pertempuran", "Memecahkan es di landasan"], "jawaban": 0, "pembahasan": "JAWABAN: Mencairkan suasana canggung\nTo break the ice berarti mencairkan suasana atau memulai percakapan agar tidak canggung.\nINGAT: Idiom tidak bisa diterjemahkan kata per kata — hafalkan makna keseluruhannya.", "topik": "idiom"},
    {"id": "e90", "pertanyaan": "Antonim dari kata ASCEND adalah ...", "pilihan": ["rise", "descend", "soar", "climb"], "jawaban": 1, "pembahasan": "JAWABAN: descend\nAscend berarti naik, antonimnya descend (turun). Climb, rise, soar adalah sinonim naik.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e91", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["There were no survivors found.", "There is a new radar station on the hill.", "There are many missiles in the bunker.", "There was several problems with the engine."], "jawaban": 3, "pembahasan": "JAWABAN: There was several problems with the engine.\nSubjek several problems adalah jamak, jadi seharusnya There were several problems, bukan There was.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e92", "pertanyaan": "The landing gear ______ when the aircraft approaches the runway.", "pilihan": ["is lowering", "lower", "is lowered", "lowered"], "jawaban": 2, "pembahasan": "JAWABAN: is lowered\nKalimat pasif simple present: landing gear di-turunkan, pola is + V3. Jadi is lowered.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e93", "pertanyaan": "Sinonim dari kata DEPLOY adalah ...", "pilihan": ["position", "hide", "destroy", "withdraw"], "jawaban": 0, "pembahasan": "JAWABAN: position\nDeploy berarti mengerahkan atau menempatkan pasukan/peralatan. Sinonim terdekat adalah position (menempatkan).\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e94", "pertanyaan": "The pilot could not see the runway because visibility was poor.\nAir traffic control ordered him to circle and wait.\nAfter ten minutes, the fog began to clear and he landed safely.\n\nWhy was the pilot ordered to circle and wait?", "pilihan": ["The runway was too short", "Visibility was poor", "The engine failed", "He was low on fuel"], "jawaban": 1, "pembahasan": "JAWABAN: Visibility was poor\nTeks menyebutkan jarak pandang buruk sehingga ATC memerintahkan pilot berputar dan menunggu sampai kabut mulai hilang.\nINGAT: Soal bacaan: jawabannya selalu ada di dalam teks, cari kalimat kuncinya.", "topik": "passive"},
    {"id": "e95", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["The pair of boots belongs to the cadet.", "Neither the radar nor the radio is working.", "Both the pilot and the co-pilot are ready.", "Either of the two routes are acceptable."], "jawaban": 3, "pembahasan": "JAWABAN: Either of the two routes are acceptable.\nEither of diikuti kata kerja singular (is), bukan are. Jadi Either of the two routes is acceptable.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e96", "pertanyaan": "If the officer ______ the order, the situation would have been different.", "pilihan": ["follows", "followed", "had followed", "has followed"], "jawaban": 2, "pembahasan": "JAWABAN: had followed\nKondisi past unreal conditional memakai if + past perfect (had followed) dengan hasil would have + V3.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "conditional"},
    {"id": "e97", "pertanyaan": "Apa arti idiom 'flying colors' dalam kalimat 'He passed the exam with flying colors'?", "pilihan": ["Dengan hasil gemilang", "Dengan banyak warna", "Dengan rasa takut", "Dengan bantuan orang lain"], "jawaban": 0, "pembahasan": "JAWABAN: Dengan hasil gemilang\nWith flying colors berarti dengan hasil yang sangat baik atau gemilang.\nINGAT: Idiom tidak bisa diterjemahkan kata per kata — hafalkan makna keseluruhannya.", "topik": "idiom"},
    {"id": "e98", "pertanyaan": "Antonim dari kata ALLY adalah ...", "pilihan": ["friend", "enemy", "supporter", "partner"], "jawaban": 1, "pembahasan": "JAWABAN: enemy\nAlly berarti sekutu/kawan, antonimnya enemy (musuh). Partner, friend, supporter adalah sinonim.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e99", "pertanyaan": "Seldom ______ the pilots complain about long patrol hours.", "pilihan": ["does", "did", "are", "do"], "jawaban": 3, "pembahasan": "JAWABAN: do\nSeldom di awal kalimat membutuhkan inversi. Subjek the pilots jamak, jadi auxiliary do + subject + verb. Jadi do.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e100", "pertanyaan": "Sinonim dari kata WING (dalam konteks militer) adalah ...", "pilihan": ["cockpit", "arm", "flank", "engine"], "jawaban": 2, "pembahasan": "JAWABAN: flank\nWing dalam konteks militer bisa berarti sayap formasi atau sisi (flank). Arm, engine, cockpit tidak sesuai.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e101", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["A series of drills were held last month.", "The staff is meeting in the briefing room.", "The information was classified as top secret.", "Two hundred meters is not far for a sniper."], "jawaban": 0, "pembahasan": "JAWABAN: A series of drills were held last month.\nA series of diikuti kata kerja singular (was held), karena subjek utamanya series. Jadi bukan were held.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e102", "pertanyaan": "The runway ______ of any debris before landing is permitted.", "pilihan": ["must clear", "must be cleared", "must cleared", "clears"], "jawaban": 1, "pembahasan": "JAWABAN: must be cleared\nKalimat pasif dengan modal: must + be + V3. Runway harus dibersihkan, jadi must be cleared.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e103", "pertanyaan": "Apa arti idiom 'to hit the ground running'?", "pilihan": ["Berlari di lapangan", "Menyerang dari darat", "Jatuh saat mendarat", "Langsung bekerja efektif sejak awal"], "jawaban": 3, "pembahasan": "JAWABAN: Langsung bekerja efektif sejak awal\nTo hit the ground running berarti langsung bekerja atau beradaptasi dengan cepat sejak awal.\nINGAT: Idiom tidak bisa diterjemahkan kata per kata — hafalkan makna keseluruhannya.", "topik": "idiom"},
    {"id": "e104", "pertanyaan": "Antonim dari kata REINFORCE adalah ...", "pilihan": ["strengthen", "support", "weaken", "fortify"], "jawaban": 2, "pembahasan": "JAWABAN: weaken\nReinforce berarti memperkuat, antonimnya weaken (melemahkan). Strengthen, support, fortify adalah sinonim.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e105", "pertanyaan": "Under no circumstances ______ the base without permission.", "pilihan": ["may you leave", "you leave", "leave you", "you may leave"], "jawaban": 0, "pembahasan": "JAWABAN: may you leave\nUnder no circumstances di awal kalimat membutuhkan inversi: modal may + subject you + verb. Jadi may you leave.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e106", "pertanyaan": "The radar operator spotted an unidentified aircraft on the screen.\nHe immediately reported it to his superior.\nTwo fighter jets were scrambled to investigate.\n\nWhat did the radar operator do after spotting the aircraft?", "pilihan": ["He ignored it", "He reported it to his superior", "He launched a missile", "He landed the plane"], "jawaban": 1, "pembahasan": "JAWABAN: He reported it to his superior\nTeks menyebutkan operator radar segera melaporkan pesawat tak dikenal kepada atasannya. Jawaban ada di kalimat kedua.\nINGAT: Soal bacaan: jawabannya selalu ada di dalam teks, cari kalimat kuncinya.", "topik": "passive"},
    {"id": "e107", "pertanyaan": "Pilih kalimat yang SALAH secara grammar:", "pilihan": ["The army was deployed to help.", "The family is moving to a new base.", "The committee has reached a decision.", "The police is patrolling the area."], "jawaban": 3, "pembahasan": "JAWABAN: The police is patrolling the area.\nThe police adalah kata benda jamak, jadi verb-nya are patrolling, bukan is. Kalimat lain benar.\nINGAT: Cari ketidakcocokan subjek–kata kerja: 'each of', 'the number of', 'news', 'equipment', 'police' punya aturan tunggal/jamak khusus.", "topik": "agreement"},
    {"id": "e108", "pertanyaan": "He suggested that the trainees ______ additional night-flight hours.", "pilihan": ["received", "receiving", "receive", "receives"], "jawaban": 2, "pembahasan": "JAWABAN: receive\nSetelah suggest (subjunctive), verb memakai bentuk dasar tanpa -s. Jadi receive, bukan receives.\nINGAT: Subjunctive setelah suggest/demand/insist/essential that: pakai kata kerja dasar (V1) tanpa -s.", "topik": "subjunctive"},
    {"id": "e109", "pertanyaan": "Sinonim dari kata AIRBASE adalah ...", "pilihan": ["military airfield", "airport", "runway", "hangar"], "jawaban": 0, "pembahasan": "JAWABAN: military airfield\nAirbase adalah pangkalan udara militer. Military airfield adalah sinonim yang paling tepat; airport untuk sipil umum.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e110", "pertanyaan": "Only after the storm had passed ______ the search-and-rescue team take off.", "pilihan": ["was", "could", "can", "does"], "jawaban": 1, "pembahasan": "JAWABAN: could\n'Only after ... had passed' menuntut inversi dengan auxiliary. Karena kejadiannya lampau dan bermakna mampu, dipakai 'could': 'Only after the storm had passed could the team take off.' 'can' salah (bukan lampau), 'does' salah (bukan lampau), 'was' tidak bisa berdiri dengan kata kerja bentuk dasar.\nINGAT: Perhatikan penanda waktu: yesterday/last week = past tense, already/since = perfect tense.", "topik": "inversion"},
    {"id": "e111", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"The Indonesian Air Force operates airbases across the archipelago, from Aceh to Papua. Each airbase is responsible for guarding the airspace above its region. Because Indonesia is an archipelagic state, the air force also cooperates with the navy to protect the sea lanes. Pilots train every day so that they can respond quickly to any intrusion. The air force also helps civilians during disasters, such as delivering food to isolated villages after an earthquake.\"\n\nPertanyaan: What is the main idea of the text?", "pilihan": ["The Air Force guards Indonesia's airspace and helps in many ways", "Disaster relief is the only duty of the Air Force", "The Air Force only works in Java and Sumatra", "The navy is responsible for airspace protection"], "jawaban": 0, "pembahasan": "JAWABAN: The Air Force guards Indonesia's airspace and helps in many ways\nTeks menjelaskan banyak tugas TNI AU: menjaga wilayah udara, bekerja sama dengan TNI AL, latihan harian, dan membantu korban bencana. Jadi gagasan utamanya adalah peran TNI AU yang beragam.\nINGAT: Soal bacaan: jawabannya selalu ada di dalam teks, cari kalimat kuncinya.", "topik": "agreement"},
    {"id": "e112", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"The Indonesian Air Force operates airbases across the archipelago, from Aceh to Papua. Each airbase is responsible for guarding the airspace above its region. Because Indonesia is an archipelagic state, the air force also cooperates with the navy to protect the sea lanes. Pilots train every day so that they can respond quickly to any intrusion. The air force also helps civilians during disasters, such as delivering food to isolated villages after an earthquake.\"\n\nPertanyaan: Who cooperates with the air force to protect the sea lanes?", "pilihan": ["Local fishermen", "The police", "The army", "The navy"], "jawaban": 3, "pembahasan": "JAWABAN: The navy\nKalimat ketiga menyebut \"the air force also cooperates with the navy to protect the sea lanes\" — jawabannya navy (TNI Angkatan Laut).\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "agreement"},
    {"id": "e113", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"The Indonesian Air Force operates airbases across the archipelago, from Aceh to Papua. Each airbase is responsible for guarding the airspace above its region. Because Indonesia is an archipelagic state, the air force also cooperates with the navy to protect the sea lanes. Pilots train every day so that they can respond quickly to any intrusion. The air force also helps civilians during disasters, such as delivering food to isolated villages after an earthquake.\"\n\nPertanyaan: Why do the pilots train every day?", "pilihan": ["So that they can respond quickly to any intrusion", "Because the archipelago is small", "To deliver food to villages", "Because they want higher ranks"], "jawaban": 0, "pembahasan": "JAWABAN: So that they can respond quickly to any intrusion\nTeks menyebut \"Pilots train every day so that they can respond quickly to any intrusion\". Perhatikan kata \"so that\" yang menandai tujuan.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "agreement"},
    {"id": "e114", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"The Indonesian Air Force operates airbases across the archipelago, from Aceh to Papua. Each airbase is responsible for guarding the airspace above its region. Because Indonesia is an archipelagic state, the air force also cooperates with the navy to protect the sea lanes. Pilots train every day so that they can respond quickly to any intrusion. The air force also helps civilians during disasters, such as delivering food to isolated villages after an earthquake.\"\n\nPertanyaan: The word \"intrusion\" in the text is closest in meaning to...", "pilihan": ["Regular training", "Heavy rain", "Illegal entry", "Friendly visit"], "jawaban": 2, "pembahasan": "JAWABAN: Illegal entry\nIntrusion berarti masuk tanpa izin (pelanggaran wilayah) — padanan terdekatnya illegal entry.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "agreement"},
    {"id": "e115", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"The Indonesian Air Force operates airbases across the archipelago, from Aceh to Papua. Each airbase is responsible for guarding the airspace above its region. Because Indonesia is an archipelagic state, the air force also cooperates with the navy to protect the sea lanes. Pilots train every day so that they can respond quickly to any intrusion. The air force also helps civilians during disasters, such as delivering food to isolated villages after an earthquake.\"\n\nPertanyaan: What does the air force do after an earthquake?", "pilihan": ["It rebuilds the houses", "It delivers food to isolated villages", "It closes the airspace", "It trains new pilots"], "jawaban": 1, "pembahasan": "JAWABAN: It delivers food to isolated villages\nKalimat terakhir: \"delivering food to isolated villages after an earthquake\".\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "agreement"},
    {"id": "e116", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Before every flight, technicians inspect the aircraft carefully. They check the engine, the landing gear, and the fuel system. A single loose bolt can cause a serious accident, so no detail is considered too small. After the inspection, the technician signs a document to confirm that the aircraft is safe to fly. Pilots rely on that signature; without it, they are not allowed to take off.\"\n\nPertanyaan: What is the text mainly about?", "pilihan": ["The importance of aircraft inspection before flight", "How to fly an aircraft safely", "How to build an aircraft engine", "The duties of pilots in the air"], "jawaban": 0, "pembahasan": "JAWABAN: The importance of aircraft inspection before flight\nSeluruh teks membahas pemeriksaan pesawat oleh teknisi sebelum terbang dan pentingnya hal itu.\nINGAT: Soal bacaan: jawabannya selalu ada di dalam teks, cari kalimat kuncinya.", "topik": "vocabulary"},
    {"id": "e117", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Before every flight, technicians inspect the aircraft carefully. They check the engine, the landing gear, and the fuel system. A single loose bolt can cause a serious accident, so no detail is considered too small. After the inspection, the technician signs a document to confirm that the aircraft is safe to fly. Pilots rely on that signature; without it, they are not allowed to take off.\"\n\nPertanyaan: Which parts do the technicians check?", "pilihan": ["The wings, the seats, and the windows", "The radar, the radio, and the cabin", "The helmet, the boots, and the parachute", "The engine, the landing gear, and the fuel system"], "jawaban": 3, "pembahasan": "JAWABAN: The engine, the landing gear, and the fuel system\nKalimat kedua menyebut \"the engine, the landing gear, and the fuel system\".\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e118", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Before every flight, technicians inspect the aircraft carefully. They check the engine, the landing gear, and the fuel system. A single loose bolt can cause a serious accident, so no detail is considered too small. After the inspection, the technician signs a document to confirm that the aircraft is safe to fly. Pilots rely on that signature; without it, they are not allowed to take off.\"\n\nPertanyaan: Why does the technician sign a document after the inspection?", "pilihan": ["To ask for extra payment", "To report the pilot to the commander", "To confirm that the aircraft is safe to fly", "To record the flight hours"], "jawaban": 2, "pembahasan": "JAWABAN: To confirm that the aircraft is safe to fly\nTeks: \"signs a document to confirm that the aircraft is safe to fly\" — tanda tangan itu bentuk pertanggungjawaban atas keamanan pesawat.\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e119", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Before every flight, technicians inspect the aircraft carefully. They check the engine, the landing gear, and the fuel system. A single loose bolt can cause a serious accident, so no detail is considered too small. After the inspection, the technician signs a document to confirm that the aircraft is safe to fly. Pilots rely on that signature; without it, they are not allowed to take off.\"\n\nPertanyaan: The phrase \"rely on\" in the text means...", "pilihan": ["Look at", "Argue with", "Write down", "Depend on"], "jawaban": 3, "pembahasan": "JAWABAN: Depend on\nRely on berarti bergantung pada (depend on).\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "vocabulary"},
    {"id": "e120", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Before every flight, technicians inspect the aircraft carefully. They check the engine, the landing gear, and the fuel system. A single loose bolt can cause a serious accident, so no detail is considered too small. After the inspection, the technician signs a document to confirm that the aircraft is safe to fly. Pilots rely on that signature; without it, they are not allowed to take off.\"\n\nPertanyaan: What happens if there is no signature?", "pilihan": ["The flight is delayed for one week", "The technician flies the aircraft", "The pilot flies a different aircraft", "The pilot is not allowed to take off"], "jawaban": 3, "pembahasan": "JAWABAN: The pilot is not allowed to take off\nKalimat terakhir: \"without it, they are not allowed to take off\".\nINGAT: Hafalkan kosakata militer: deploy, convoy, perimeter, reconnaissance, intelligence, morale, logistics.", "topik": "conditional"},
    {"id": "e121", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Recruits at the air force academy wake up before sunrise. They run, drill, and study theory until late afternoon. Instructors say the goal is not only physical strength but also the ability to make decisions under pressure. Many recruits find the first month the hardest, yet most of them say the training changed their character. Discipline, they learn, is not punishment; it is a habit that keeps the team alive.\"\n\nPertanyaan: What is the main idea of the text?", "pilihan": ["The history of the air force academy", "The aim and the effect of training at the air force academy", "Why instructors are strict with recruits", "How to wake up early every day"], "jawaban": 1, "pembahasan": "JAWABAN: The aim and the effect of training at the air force academy\nTeks menjelaskan tujuan latihan (kekuatan fisik dan kemampuan mengambil keputusan) serta dampaknya pada karakter taruna.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e122", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Recruits at the air force academy wake up before sunrise. They run, drill, and study theory until late afternoon. Instructors say the goal is not only physical strength but also the ability to make decisions under pressure. Many recruits find the first month the hardest, yet most of them say the training changed their character. Discipline, they learn, is not punishment; it is a habit that keeps the team alive.\"\n\nPertanyaan: When do the recruits wake up?", "pilihan": ["After breakfast", "In the late afternoon", "Before sunrise", "At sunrise"], "jawaban": 2, "pembahasan": "JAWABAN: Before sunrise\nKalimat pertama: \"Recruits at the air force academy wake up before sunrise\".\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e123", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Recruits at the air force academy wake up before sunrise. They run, drill, and study theory until late afternoon. Instructors say the goal is not only physical strength but also the ability to make decisions under pressure. Many recruits find the first month the hardest, yet most of them say the training changed their character. Discipline, they learn, is not punishment; it is a habit that keeps the team alive.\"\n\nPertanyaan: Why is the training not only about physical strength?", "pilihan": ["Because the academy has no sport fields", "Because officers must also make decisions under pressure", "Because instructors are old", "Because physical training is not important"], "jawaban": 1, "pembahasan": "JAWABAN: Because officers must also make decisions under pressure\nTeks: \"the goal is not only physical strength but also the ability to make decisions under pressure\" — di lapangan, keputusan cepat saat tertekan sama pentingnya.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e124", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Recruits at the air force academy wake up before sunrise. They run, drill, and study theory until late afternoon. Instructors say the goal is not only physical strength but also the ability to make decisions under pressure. Many recruits find the first month the hardest, yet most of them say the training changed their character. Discipline, they learn, is not punishment; it is a habit that keeps the team alive.\"\n\nPertanyaan: The phrase \"under pressure\" in the text means...", "pilihan": ["In a difficult or stressful situation", "With loud music", "Under a heavy object", "Below the standard"], "jawaban": 0, "pembahasan": "JAWABAN: In a difficult or stressful situation\n\"Under pressure\" berarti dalam tekanan atau situasi sulit, bukan tekanan fisik.\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e125", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Recruits at the air force academy wake up before sunrise. They run, drill, and study theory until late afternoon. Instructors say the goal is not only physical strength but also the ability to make decisions under pressure. Many recruits find the first month the hardest, yet most of them say the training changed their character. Discipline, they learn, is not punishment; it is a habit that keeps the team alive.\"\n\nPertanyaan: What do most recruits say about the training?", "pilihan": ["It was easy", "It changed their character", "It damaged their health", "It was too short"], "jawaban": 1, "pembahasan": "JAWABAN: It changed their character\nTeks: \"most of them say the training changed their character\".\nINGAT: Ada kata negatif di awal kalimat (hardly, seldom, rarely, not only) maka harus inversi: auxiliary + subjek + kata kerja.", "topik": "inversion"},
    {"id": "e126", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Unmanned aerial vehicles, or drones, are now used for more than surveillance. In disaster areas, drones map the damage and help rescuers find survivors faster. In remote regions, they deliver medicine to clinics that cannot be reached by road. However, the use of drones also raises questions about privacy and airspace safety. For that reason, operators must be trained and licensed, and every flight must follow national regulations.\"\n\nPertanyaan: What is the main idea of the text?", "pilihan": ["The growing uses of drones and the need to regulate them", "How to build a drone at home", "The history of unmanned aircraft", "Why drones are dangerous for everyone"], "jawaban": 0, "pembahasan": "JAWABAN: The growing uses of drones and the need to regulate them\nTeks membahas manfaat drone (bencana, daerah terpencil) sekaligus alasan penggunaannya harus diatur: privasi dan keselamatan ruang udara.\nINGAT: Kalimat pasif: be (is/are/was/were/must be) + V3.", "topik": "passive"},
    {"id": "e127", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Unmanned aerial vehicles, or drones, are now used for more than surveillance. In disaster areas, drones map the damage and help rescuers find survivors faster. In remote regions, they deliver medicine to clinics that cannot be reached by road. However, the use of drones also raises questions about privacy and airspace safety. For that reason, operators must be trained and licensed, and every flight must follow national regulations.\"\n\nPertanyaan: What can drones do in disaster areas?", "pilihan": ["Build temporary houses", "Deliver fuel to the airport", "Map the damage and help find survivors", "Repair broken roads"], "jawaban": 2, "pembahasan": "JAWABAN: Map the damage and help find survivors\nTeks: \"drones map the damage and help rescuers find survivors faster\".\nINGAT: Kalimat pasif: be (is/are/was/were/must be) + V3.", "topik": "passive"},
    {"id": "e128", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Unmanned aerial vehicles, or drones, are now used for more than surveillance. In disaster areas, drones map the damage and help rescuers find survivors faster. In remote regions, they deliver medicine to clinics that cannot be reached by road. However, the use of drones also raises questions about privacy and airspace safety. For that reason, operators must be trained and licensed, and every flight must follow national regulations.\"\n\nPertanyaan: What do drones deliver to remote regions?", "pilihan": ["Fuel", "Uniforms", "Weapons", "Medicine"], "jawaban": 3, "pembahasan": "JAWABAN: Medicine\nTeks: \"In remote regions, they deliver medicine to clinics that cannot be reached by road\".\nINGAT: Kalimat pasif: be (is/are/was/were/must be) + V3.", "topik": "passive"},
    {"id": "e129", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Unmanned aerial vehicles, or drones, are now used for more than surveillance. In disaster areas, drones map the damage and help rescuers find survivors faster. In remote regions, they deliver medicine to clinics that cannot be reached by road. However, the use of drones also raises questions about privacy and airspace safety. For that reason, operators must be trained and licensed, and every flight must follow national regulations.\"\n\nPertanyaan: Why must drone operators be trained and licensed?", "pilihan": ["Because drones cannot fly in cities", "Because the government sells the licenses", "Because drones are expensive", "Because privacy and airspace safety must be protected"], "jawaban": 3, "pembahasan": "JAWABAN: Because privacy and airspace safety must be protected\nTeks menjelaskan penggunaan drone menimbulkan pertanyaan soal privasi dan keselamatan ruang udara, sehingga operator harus terlatih dan berlisensi serta setiap penerbangan mengikuti aturan.\nINGAT: Kalimat pasif: be (is/are/was/were/must be) + V3.", "topik": "passive"},
    {"id": "e130", "pertanyaan": "Bacaan berikut untuk soal ini:\n\"Unmanned aerial vehicles, or drones, are now used for more than surveillance. In disaster areas, drones map the damage and help rescuers find survivors faster. In remote regions, they deliver medicine to clinics that cannot be reached by road. However, the use of drones also raises questions about privacy and airspace safety. For that reason, operators must be trained and licensed, and every flight must follow national regulations.\"\n\nPertanyaan: The word \"surveillance\" in the text is closest in meaning to...", "pilihan": ["Carrying a load", "Monitoring an area", "Building a map", "Repairing a machine"], "jawaban": 1, "pembahasan": "JAWABAN: Monitoring an area\nSurveillance berarti pengawasan atau pemantauan suatu wilayah.\nINGAT: Kalimat pasif: be (is/are/was/were/must be) + V3.", "topik": "passive"}
]};
